function handleChartMove(event){if(!chartGeometry)return;const g=chartGeometry,rect=$('price-chart').getBoundingClientRect(),px=event.clientX-rect.left,index=Math.max(0,Math.min(g.bars.length-1,Math.floor((px-g.left)/g.cw*g.bars.length)));chartHover=index;drawChart();const b=g.bars[index],tip=$('chart-tooltip');tip.replaceChildren(el('strong',b.date),el('div',`開 ${number(b.open,2)}　高 ${number(b.high,2)}`),el('div',`低 ${number(b.low,2)}　收 ${number(b.close,2)}`),el('div',`成交 ${number(b.volume)} 股`));const ms=g.markerByDate.get(b.date)||[];if(ms.length)tip.append(el('div',`訊號 ${ms.length} 項：`+ms.slice(0,2).map(m=>m.name||m.strategy_id).join('、')));tip.hidden=false;tip.style.left=Math.max(4,Math.min(px+12,g.w-235))+'px';tip.style.top='12px';}
function renderCatalog(){const query=$('catalog-search').value.trim().toLowerCase(),status=$('catalog-status').value,family=$('catalog-family').value;const active=state.catalog.filter(x=>x.status==='active').length;const summary=[];for(const [n,label]of[[state.catalog.length,'已收錄策略'],[active,'已實作規則'],[state.catalog.length-active,'待接入研究']]){const d=el('div');d.append(el('strong',number(n)),el('span',label));summary.push(d);}summary.push(el('p','這是一份持續擴充的策略地圖，並非所有已知策略的全集。已實作表示能計算，尚不代表能獲利。'));replace('catalog-summary',...summary);const list=state.catalog.filter(s=>(status==='all'||s.status===status)&&(family==='all'||s.family===family)&&(!query||`${s.name} ${s.id} ${s.description||''} ${families[s.family]||s.family}`.toLowerCase().includes(query)));const cards=list.map(s=>{const card=el('article',undefined,'strategy-card'),head=el('div',undefined,'strategy-top');head.append(el('span',(families[s.family]||s.family)+' · '+(kinds[s.kind]||s.kind)),tag(s.status==='active'?(s.signal_only?'已接入訊號 · 尚未接回測':'已實作'):'待接入',s.status==='active'?'green':'neutral'));card.append(head,el('h3',s.name),el('p',s.description||s.rule||'詳細條件請查看策略來源。'));if(Array.isArray(s.data_gaps)&&s.data_gaps.length)card.append(el('p',s.data_gaps.join('；'),'strategy-gap'));const details=el('details');details.append(el('summary','資料需求與來源'));const ul=el('ul');for(const item of s.required_data||[])ul.append(el('li',item));for(const url of s.source_urls||[]){const li=el('li');if(/^https?:\/\//.test(url)){const a=el('a',url);a.href=url;a.target='_blank';a.rel='noopener noreferrer';li.append(a);}else li.textContent=url;ul.append(li);}details.append(ul);card.append(details);return card;});replace('catalog-grid',...(cards.length?cards:[empty('沒有符合的策略','請調整搜尋或篩選條件。')]));}
async function loadStudies(){if(state.studies)return;try{const results=await Promise.allSettled([api('/studies'),api('/archive')]);if(results[0].status==='fulfilled'){state.studies=results[0].value;renderStudies();}else throw results[0].reason;if(results[1].status==='fulfilled'){state.archive=results[1].value;replace('backtest-archive');renderArchive($('backtest-archive'));}}catch(e){replace('studies-list',el('p','歷史研究讀取失敗：'+e.message,'caption'));}}
function renderStudies(){const raw=state.studies,rows=Array.isArray(raw)?raw:raw?.summary||raw?.rows||raw?.studies||[];const subset=rows.filter(x=>String(x.year)==='all'&&x.horizon===20).sort((a,b)=>(a.name||a.strategy_id).localeCompare(b.name||b.strategy_id,'zh-TW'));const items=subset.map(s=>{const r=el('div',undefined,'study-row'),left=el('div'),metric=el('div',pct(s.mean_excess_vs0050),'study-metric');left.append(el('strong',s.name||s.strategy_id),el('p',`${number(s.evaluated)} 筆可評估 · 持有 ${s.horizon} 日 · 勝率 ${pct(s.win_rate,1)}`));metric.append(el('small','平均超額報酬 · 非累積'));r.append(left,metric);return r;});replace('studies-list',...(items.length?items:[el('p','尚無可呈現的已保存比較。','caption')]));}
async function runBacktest(event){event.preventDefault();const button=$('backtest-submit');button.disabled=true;$('backtest-status').hidden=false;$('backtest-status').className='alert';$('backtest-status').textContent='正在依選定期間重新彙總訊號與同期基準…';try{const payload={strategy_id:$('backtest-strategy').value,start:$('backtest-start').value,end:$('backtest-end').value,horizon:Number($('backtest-holding').value),mode:'signal_study'};let job=await api('/backtests',{method:'POST',body:JSON.stringify(payload)});for(let i=0;job.status!=='completed'&&i<120;i++){if(['failed','error'].includes(job.status))throw Error(job.error||'回測未完成');await new Promise(r=>setTimeout(r,1500));job=await api('/backtests/'+encodeURIComponent(job.job_id));}if(job.status!=='completed')throw Error('回測仍在執行，稍後可再次查詢同一份實驗。');renderBacktest(job.result||job,job.job_id);$('backtest-status').textContent='研究完成。以下為每筆訊號的結果分布，不是帳戶累積報酬。';}catch(error){$('backtest-status').className='alert error';$('backtest-status').textContent=error.message;}finally{button.disabled=false;}}
function renderBacktest(result,jobId){const host=$('backtest-result');host.className='panel';const stats=result.stats||{},head=el('div',undefined,'result-heading'),title=el('div');title.append(el('h2',result.name||state.catalog.find(x=>x.id===result.strategy_id)?.name||result.strategy_id),el('p',`${result.start} → ${result.end} · 持有 ${result.horizon} 個交易日`));head.append(title,tag('訊號獨立研究','green'));const cards=el('div',undefined,'result-metrics');for(const [label,formatted]of[['可評估訊號',number(stats.evaluated)],['獲利勝率',pct(stats.win_rate,1)],['平均扣費報酬',pct(stats.mean_net_return)],['報酬中位數',pct(stats.median_net_return)],['平均超越 0050',pct(stats.mean_excess_vs0050)],['跑贏基準比例',pct(stats.beat_benchmark_rate,1)]]){const c=el('div',undefined,'result-metric');c.append(el('small',label),el('strong',formatted));cards.append(c);}const body=el('div',undefined,'result-body');body.append(el('h3','相同持有期間的平均扣費報酬'));const max=Math.max(Math.abs(stats.mean_net_return||0),Math.abs(stats.mean_benchmark_net_return||0),.001);for(const [label,n]of[['策略訊號',stats.mean_net_return],['同期 0050',stats.mean_benchmark_net_return]]){const l=el('div',undefined,'comparison-label');l.append(el('span',label),el('strong',pct(n)));const bar=el('div',undefined,'comparison-bar'),fill=el('span');fill.style.width=(Math.abs(n||0)/max*100)+'%';if(n<0)fill.style.background='#cc8e7d';bar.append(fill);body.append(l,bar);}body.append(el('p',`樣本 ${number(stats.events)} 筆；未滿持有期 ${number(stats.immature)} 筆；個股行情缺漏 ${number(stats.stock_path_missing)} 筆；基準缺漏 ${number(stats.benchmark_path_missing)} 筆。重疊訊號並非獨立樣本。沒有模擬共用資金，所以不提供帳戶累積報酬或最大回撤。`,'result-note'));const years=result.yearly||[];if(years.length){const wrap=el('div',undefined,'result-table-wrap'),table=el('table'),thead=el('thead'),tr=el('tr');for(const label of['年度','可評估','勝率','平均報酬','超越 0050'])tr.append(el('th',label));thead.append(tr);const tbody=el('tbody');for(const year of years){const row=el('tr');for(const v of[year.year,number(year.evaluated),pct(year.win_rate,1),pct(year.mean_net_return),pct(year.mean_excess_vs0050)])row.append(el('td',v));tbody.append(row);}table.append(thead,tbody);wrap.append(table);body.append(wrap);}const coverage=result.signal_coverage;if(coverage)body.prepend(el('p',`實際訊號出現期間：${coverage.first_event_date||'無訊號'} → ${coverage.last_event_date||'無訊號'}。${coverage.note||''}`,'result-note'));if(result.entry_price||result.exit_price)body.append(el('p',`進場假設：${executionLabel(result.entry_price)}；出場假設：${executionLabel(result.exit_price)}。${result.explanation||''}`,'result-note'));if(jobId)body.append(eventTable(result,jobId));host.replaceChildren(head,cards,body);}
function eventTable(result,jobId){const details=el('details',undefined,'backtest-events');details.append(el('summary',`檢視全部 ${number(result.event_count)} 筆訊號與進出場日期`));const wrap=el('div',undefined,'account-trades'),table=el('table'),head=el('tr');for(const label of ['訊號日期','股票','次日進場','期末出場','扣費報酬','超越 0050','狀態'])head.append(el('th',label));const th=el('thead');th.append(head);const body=el('tbody');table.append(th,body);wrap.append(table);details.append(wrap);const pager=el('div',undefined,'table-footer'),label=el('span'),buttons=el('div'),prev=el('button','‹','mini-button'),next=el('button','›','mini-button');buttons.append(prev,next);pager.append(label,buttons);details.append(pager);let page=0,events=result.events||[];function render(){body.replaceChildren();for(const r of events){const tr=el('tr');for(const v of [r.signal_date,r.stock_id,r.entry_date||'—',r.exit_date||'—',pct(r.net_return),pct(r.excess_vs0050),({evaluated:'已評估',immature:'未滿持有期',stock_path_missing:'個股缺行情',benchmark_path_missing:'基準缺行情'})[r.status]||r.status])tr.append(el('td',v));body.append(tr);}label.textContent=`${result.event_count?page*200+1:0}–${Math.min((page+1)*200,result.event_count)} / ${number(result.event_count)} 筆`;prev.disabled=page===0;next.disabled=(page+1)*200>=result.event_count;}async function load(change){prev.disabled=next.disabled=true;try{const nextPage=page+change,data=await api(`/backtests/${encodeURIComponent(jobId)}/events?offset=${nextPage*200}&limit=200`);events=data.events||data.rows||[];page=nextPage;render();}catch(error){label.textContent=error.message;prev.disabled=page===0;next.disabled=(page+1)*200>=result.event_count;}}prev.addEventListener('click',()=>load(-1));next.addEventListener('click',()=>load(1));render();return details;}
async function loadResearch(){if(state.research){renderResearch();return;}try{const [r,a]=await Promise.allSettled([api('/research'),api('/archive')]);state.research=r.status==='fulfilled'?r.value:{status:'not_available',note:r.reason?.message};state.archive=a.status==='fulfilled'?a.value:null;renderResearch();}catch(error){replace('research-body',empty('研究資料未就緒',error.message));}}
